<?php
namespace App\Services;
use Illuminate\Http\Client\RequestException;
use Illuminate\Support\Facades\Http;
class SearchConsole {
 const READ='https://www.googleapis.com/auth/webmasters.readonly',WRITE='https://www.googleapis.com/auth/webmasters',INDEXING='https://www.googleapis.com/auth/indexing';
 // Google's addresses. Tests may point them at a local stand-in, but never on a production site.
 public static function base(string $real):string {$o=env('GOOGLE_API_BASE');return $o&&config('app.env')!=='production'?rtrim($o,'/'):$real;}
 public static function ready():bool {$p=Settings::providers()['analytics']??[];return !empty($p['searchConsoleProperty'])&&!empty($p['searchConsoleServiceAccount']);}
 public static function property():string {return trim(Settings::providers()['analytics']['searchConsoleProperty']??'');}
 /** An access token for the saved service account, or a plain-language 422 the owner can act on. */
 public static function token(string $scope):string {abort_unless(self::ready(),422,'Add the Search Console property and the Google service-account JSON in Integrations first.');try{$a=json_decode(Settings::providers()['analytics']['searchConsoleServiceAccount'],true,64,JSON_THROW_ON_ERROR);}catch(\JsonException){abort(422,'The Google service-account JSON is not valid. Open the downloaded .json file in Notepad, copy everything from { to } and paste it again.');}abort_unless(is_array($a)&&($a['type']??'')==='service_account'&&!empty($a['client_email'])&&!empty($a['private_key']),422,'That JSON is not a service-account key. In Google Cloud use IAM & Admin > Service accounts > Keys > Add key > JSON.');$enc=fn($v)=>rtrim(strtr(base64_encode($v),'+/','-_'),'=');$jwt=$enc(json_encode(['alg'=>'RS256','typ'=>'JWT'])).'.'.$enc(json_encode(['iss'=>$a['client_email'],'scope'=>$scope,'aud'=>'https://oauth2.googleapis.com/token','iat'=>time(),'exp'=>time()+3600]));abort_unless(@openssl_sign($jwt,$signature,$a['private_key'],OPENSSL_ALGO_SHA256),422,'The private key inside the service-account JSON could not be read. Download a fresh JSON key and paste it again.');$res=Http::asForm()->timeout(15)->post(self::base('https://oauth2.googleapis.com').'/token',['grant_type'=>'urn:ietf:params:oauth:grant-type:jwt-bearer','assertion'=>$jwt.'.'.$enc($signature)]);abort_unless($res->successful()&&$res->json('access_token'),422,'Google refused the service-account key ('.($res->json('error_description')?:$res->status()).'). The key may have been deleted; create a new JSON key and paste it again.');return $res->json('access_token');}
 /** Turns a Google API failure into a sentence that says what to fix. */
 public static function explain(RequestException $e,string $what):never {$s=$e->response->status();$m=(string)($e->response->json('error.message')?:'');abort(422,match(true){$s===403&&(str_contains($m,'has not been used')||str_contains($m,'is disabled'))=>"$what: the API is switched off in your Google Cloud project. Enable it (see the guide) and try again in five minutes.",$s===403=>"$what: Google says the service account has no permission on ".self::property().'. In Search Console > Settings > Users and permissions, add the service-account email as Owner.',$s===404=>"$what: Google cannot find the property ".self::property().'. It must match Search Console exactly, for example sc-domain:cvtara.com.',$s===429=>"$what: Google's daily limit is used up. It resets at midnight Pacific time.",default=>"$what failed ($s".($m!==''?': '.mb_substr($m,0,200):'').').'});}
 public function sync():array {$token=self::token(self::READ);$result=['source'=>'Google Search Console API','startDate'=>now()->subDays(31)->toDateString(),'endDate'=>now()->subDays(3)->toDateString(),'updatedAt'=>now()->toIso8601String()];foreach(['query','page'] as $dim){try{$d=Http::withToken($token)->timeout(20)->post(self::base('https://www.googleapis.com').'/webmasters/v3/sites/'.rawurlencode(self::property()).'/searchAnalytics/query',['startDate'=>$result['startDate'],'endDate'=>$result['endDate'],'dimensions'=>[$dim],'rowLimit'=>5000])->throw()->json();}catch(RequestException $e){self::explain($e,'Search Console sync');}$result[$dim]=array_map(fn($r)=>['key'=>$r['keys'][0],'clicks'=>$r['clicks'],'impressions'=>$r['impressions'],'ctr'=>$r['ctr'],'position'=>$r['position']],$d['rows']??[]);}Settings::put('searchData',$result);return $result;}
 /** Tells Google to re-read the sitemap now (the official route; the old "ping" address was retired in 2023). Needs Owner or Full permission. */
 public static function submitSitemap(string $sitemap):void {$token=self::token(self::WRITE);try{Http::withToken($token)->timeout(20)->withBody('','text/plain')->put(self::base('https://www.googleapis.com').'/webmasters/v3/sites/'.rawurlencode(self::property()).'/sitemaps/'.rawurlencode($sitemap))->throw();}catch(RequestException $e){self::explain($e,'Sitemap submission');}}
}
